  padding: 64px 0;
  background: var(--paper);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  overflow: hidden;
}

.carousel-track-wrap {
  position: relative;
  overflow: hidden;
  width: 100%;
  cursor: default;

  // Soft fade masks on the edges so logos appear to flow in/out
  &::before,
  &::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 72px;
    z-index: 2;
    pointer-events: none;
  }
  &::before { left: 0; background: linear-gradient(to right, var(--paper), transparent); }
  &::after  { right: 0; background: linear-gradient(to left, var(--paper), transparent); }

  &:hover .carousel-track { animation-play-state: paused; }
}

.carousel-track {
  display: flex;
  align-items: center;
  gap: 48px;
  width: max-content;
  animation: carousel-scroll 32s linear infinite;
  will-change: transform;
}

.carousel-item {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 110px;

  img {
    max-height: 110px;
    width: auto;
    max-width: 220px;
    object-fit: contain;
    opacity: 0.75;
    filter: grayscale(100%);
    transition: opacity 0.2s, filter 0.2s;

    &:hover { opacity: 1; filter: grayscale(0%); }
  }
}

@keyframes carousel-scroll {
  from { transform: translateX(0); }
  to   { transform: translateX(calc(-100% / 5)); } // one of the 5 identical sets
}

